def is_sorted(config):
    """Checks if the configuration has at most one boundary between A and C."""
    if not config:
        return True
    boundaries = 0
    for i in range(len(config) - 1):
        if config[i] != config[i+1]:
            boundaries += 1
    return boundaries <= 1

def perform_operation(config, k):
    N = len(config)
    if k < 1 or k > N:
        raise ValueError("k must be between 1 and N")

    # k-th coin is at index k-1
    k_idx = k - 1
    M = config[k_idx]

    # 1. Find start index s
    s = k_idx
    while s > 0 and config[s-1] == M:
        s -= 1

    # 2. Find end index e
    e = k_idx
    while e < N - 1 and config[e+1] == M:
        e += 1

    # Subsequence is config[s:e+1]
    subsequence = config[s:e+1]

    # Remaining parts
    prefix = config[:s]
    suffix = config[e+1:]

    # New configuration: Subsequence moves to the front
    new_config = subsequence + prefix + suffix
    return new_config

def simulate_process(initial_config, k, max_steps=100):
    current_config = list(initial_config)
    history = {tuple(current_config)}

    for step in range(max_steps):
        try:
            next_config_str = perform_operation("".join(current_config), k)
            next_config = list(next_config_str)
        except ValueError as e:
            return "Error: " + str(e), False # Should not happen with fixed k

        # Check for stability (stuck state)
        if tuple(next_config) in history:
            # Stuck state reached
            return next_config_str, is_sorted(next_config)

        current_config = next_config
        history.add(tuple(current_config))

        # Check termination condition immediately after transition
        if is_sorted(current_config):
            return next_config_str, True

    # If max steps reached, assume process hasn't resolved to sorted state
    return "".join(current_config), False

